//
//  PartEditing.swift
//  GBGCore
//
//  Seq's step-entry editor model, layered on Part's existing contiguous-tiling invariant (see
//  Part.swift's header comment) rather than replacing it - ScorePlayer's real-time cursor still
//  needs every sample covered. The editor's own view of a Part is different: only the sounding
//  notes (amplitude > 0) are real objects to the user, each independent in time, and the silent
//  rests between them are an implementation detail regenerated by `retile()` after every edit.
//  So, unlike `moveNoteBoundary` (which grows/shrinks a shared neighbor), moving one note's edge
//  here never drags a neighboring sounding note along with it - it can only run into one and stop.
//
//  Every note is a pitch bend: startFrequency -> endFrequency shaped by its transition profile.
//  A plain held note is just the case startFrequency == endFrequency, so the legacy `.flat`
//  transition (which ignored endFrequency entirely) is folded away by `normalizeFlatTransitions()`.
//

import Foundation

public extension Part {
    /// The notes a person actually sees and edits - everything but the silent filler rests.
    var soundingNotes: [Note] { notes.filter { $0.amplitude > 0 } }

    /// Rebuilds the silent rests so the sounding notes tile the timeline from 0 again: drops every
    /// existing rest, sorts the sounding notes by start time, trims any overlap (a later note wins
    /// its own start; the earlier one is cut short to meet it), and fills each gap - including any
    /// leading gap before the first note - with a fresh zero-amplitude rest. A rest takes the
    /// following note's start pitch, which keeps a MIDI receiver's last pitch-bend sensible.
    func retile() {
        let sounding = soundingNotes.sorted { $0.startTime < $1.startTime }
        for (index, note) in sounding.enumerated() where index + 1 < sounding.count {
            let next = sounding[index + 1]
            if note.endTime > next.startTime { note.endTime = next.startTime }
        }
        var rebuilt: [Note] = []
        var cursor = 0
        for note in sounding where note.endTime > note.startTime {
            if note.startTime > cursor {
                rebuilt.append(Note(startTime: cursor, endTime: note.startTime, startFrequency: note.startFrequency, endFrequency: note.startFrequency, amplitude: 0))
            }
            rebuilt.append(note)
            cursor = note.endTime
        }
        notes = rebuilt
        currentNoteIndex = 0
    }

    /// The span a sounding `note` may occupy without overlapping its sounding neighbors:
    /// from the previous note's end (or 0) to the next note's start (or unbounded).
    func freeSpan(around note: Note) -> ClosedRange<Int> {
        let others = soundingNotes.filter { $0 !== note }
        let lower = others.filter { $0.startTime < note.startTime }.map(\.endTime).max() ?? 0
        let upper = others.filter { $0.startTime >= note.startTime }.map(\.startTime).min() ?? Int.max
        return lower...max(lower, upper)
    }

    /// Moves one edge of `note` to `newTime`, clamped so the note stays at least
    /// `minimumNoteLength` long and never overlaps a sounding neighbor. Returns the time actually
    /// applied, or nil if `note` isn't a sounding note in this Part.
    @discardableResult
    func setEdge(_ edge: NoteEdge, of note: Note, to newTime: Int, minimumNoteLength: Int = 1) -> Int? {
        guard soundingNotes.contains(where: { $0 === note }) else { return nil }
        let free = freeSpan(around: note)
        let clamped: Int
        switch edge {
        case .start:
            clamped = min(max(newTime, free.lowerBound), note.endTime - minimumNoteLength)
            note.startTime = max(free.lowerBound, clamped)
        case .end:
            clamped = max(min(newTime, free.upperBound), note.startTime + minimumNoteLength)
            note.endTime = min(free.upperBound, clamped)
        }
        retile()
        return edge == .start ? note.startTime : note.endTime
    }

    /// Slides the whole of `note` so it starts at `newStart`, keeping its length, clamped
    /// between its sounding neighbors. Returns the start time actually applied.
    @discardableResult
    func moveNote(_ note: Note, toStart newStart: Int) -> Int? {
        guard soundingNotes.contains(where: { $0 === note }) else { return nil }
        let length = note.endTime - note.startTime
        let free = freeSpan(around: note)
        let latestStart = free.upperBound == Int.max ? Int.max : free.upperBound - length
        let clamped = latestStart < free.lowerBound ? note.startTime : min(max(newStart, free.lowerBound), latestStart)
        note.startTime = clamped
        note.endTime = clamped + length
        retile()
        return clamped
    }

    /// Removes a sounding note outright - the rests around it merge into one.
    func removeNote(_ note: Note) {
        notes.removeAll { $0 === note }
        retile()
    }

    /// Places a new sounding note over [startTime, endTime), overwriting whatever this Part had
    /// there (same carve rule as insertNote), with the given transition profile.
    @discardableResult
    func placeNote(startTime: Int, endTime: Int, startFrequency: Double, endFrequency: Double, amplitude: Double = 1, profile: TransitionKind = .linear) -> Note {
        let note = insertNote(startTime: startTime, endTime: endTime, startFrequency: startFrequency, endFrequency: endFrequency, amplitude: amplitude)
        note.selectTransition(profile == .flat ? .linear : profile)
        retile()
        return note
    }

    /// Folds the legacy `.flat` transition into the unified model: a flat note always sounded at
    /// its startFrequency no matter what endFrequency said, so it becomes a linear bend with
    /// endFrequency == startFrequency - identical sound, and its end handle now tells the truth.
    /// Rests are left alone (their pitch is never heard).
    func normalizeFlatTransitions() {
        for note in notes where note.amplitude > 0 && note.transitionKind == .flat {
            note.endFrequency = note.startFrequency
            note.selectTransition(.linear)
        }
    }
}

/// A restorable copy of a Part's contents, for undo. Keeps the original Note objects (and puts
/// their field values back on restore) rather than cloning them, so anything holding a
/// reference to a note - Seq's selection - still points at the same note after an undo.
public struct PartSnapshot {
    fileprivate struct NoteState {
        let note: Note
        let startTime: Int
        let endTime: Int
        let startFrequency: Double
        let endFrequency: Double
        let amplitude: Double
        let transition: Transition
        let envelope: Envelope
        let recordedPitchBend: [Double]?
    }
    fileprivate let states: [NoteState]
}

public extension Part {
    func snapshot() -> PartSnapshot {
        PartSnapshot(states: notes.map {
            .init(note: $0, startTime: $0.startTime, endTime: $0.endTime, startFrequency: $0.startFrequency, endFrequency: $0.endFrequency,
                  amplitude: $0.amplitude, transition: $0.transition, envelope: $0.envelope, recordedPitchBend: $0.recordedPitchBend)
        })
    }

    func restore(_ snapshot: PartSnapshot) {
        for state in snapshot.states {
            let note = state.note
            note.startTime = state.startTime
            note.endTime = state.endTime
            note.startFrequency = state.startFrequency
            note.endFrequency = state.endFrequency
            note.amplitude = state.amplitude
            note.transition = state.transition
            note.envelope = state.envelope
            note.recordedPitchBend = state.recordedPitchBend
        }
        notes = snapshot.states.map(\.note)
        currentNoteIndex = 0
    }
}

public extension Part {
    /// The note covering `time` (start inclusive, end exclusive - the same rule ScorePlayer
    /// plays by), or nil past the end. Unlike `getCurrentNote`, this leaves the Part's playback
    /// cursor alone and logs nothing, so it's safe to call from the main thread while
    /// ScorePlayer is advancing the same Part on the audio thread.
    func note(at time: Int) -> Note? {
        var low = 0, high = notes.count - 1
        while low <= high {
            let mid = (low + high) / 2
            let candidate = notes[mid]
            if time < candidate.startTime { high = mid - 1 }
            else if time >= candidate.endTime { low = mid + 1 }
            else { return candidate }
        }
        return nil
    }
}

/// The pitch a note actually sounds at each end. For most profiles that's just
/// startFrequency/endFrequency; a Recorded note adds its contour's cents offset on top, so its
/// real endpoints can sit well away from those base values (a raw live capture's base is the
/// MIDI anchor pitch, middle C). Editing goes through these so handles sit on the drawn line and
/// typed pitches mean what you hear.
public extension Note {
    func endpointFrequency(_ edge: NoteEdge) -> Double {
        getCurrentFrequency(percentComplete: edge == .start ? 0 : 1)
    }

    /// Sets the pitch this note sounds at `edge` to `frequency`, by adjusting the base pitch at
    /// that end. Every profile but the legacy Flat runs its base from start (at 0) to end (at 1),
    /// so this is exact; a Flat note is first converted to its equal-pitch Linear equivalent.
    func setEndpointFrequency(_ edge: NoteEdge, to frequency: Double) {
        guard frequency > 0 else { return }
        if transitionKind == .flat {
            endFrequency = startFrequency
            selectTransition(.linear)
        }
        let offsetFactor = pow(2, transition.centsOffset(percentComplete: edge == .start ? 0 : 1) / 1200)
        switch edge {
        case .start: startFrequency = frequency / offsetFactor
        case .end: endFrequency = frequency / offsetFactor
        }
    }

    /// Switches the profile while keeping the pitches the note sounds at both ends. Without
    /// this, turning a raw Recorded capture to Linear would drop it to its middle-C base; with
    /// it, Recorded -> Linear -> Recorded comes back exactly.
    func selectProfile(_ kind: TransitionKind) {
        let start = endpointFrequency(.start)
        let end = endpointFrequency(.end)
        selectTransition(kind == .flat ? .linear : kind)
        setEndpointFrequency(.start, to: start)
        setEndpointFrequency(.end, to: end)
    }
}
